def prime_factorization(n):
    """Returns a dictionary of prime factors and their exponents."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_x_squared(x):
    """Calculates tau(x^2), the number of divisors of x^2."""
    if x == 1:
        return 1 # tau(1^2) = tau(1) = 1

    factors = prime_factorization(x)
    tau_val = 1
    for p, a in factors.items():
        # If x = p^a * ..., then x^2 = p^(2a) * ...
        # The exponent for p in x^2 is 2a.
        # The contribution to tau(x^2) is (2a + 1).
        tau_val *= (2 * a + 1)
    return tau_val

def calculate_N_x(x):
    """Calculates N(x) using the formula N(x) = (tau(x^2) - 1) / 2."""
    if x == 1:
        # tau(1^2) = 1. (1 - 1) / 2 = 0. N(1) = 0.
        return 0
    tau = tau_x_squared(x)
    if (tau - 1) % 2 != 0:
        # This should theoretically never happen if the formula is correct
        # since tau(x^2) is always odd (it's a product of odd numbers 2a+1).
        # If tau is odd, tau-1 is even.
        raise ValueError("tau(x^2) must be odd.")

    return (tau - 1) // 2

# Compute and log N(x) for x up to 100
results = {}
for x in range(1, 101):
    try:
        N_x = calculate_N_x(x)
        results[x] = N_x
    except ValueError as e:
        results[x] = f"Error: {e}"

print("Calculated N(x) for x=1 to 100:")
for x, N_x in results.items():
    print(f"x={x}: N(x) = {N_x}")

