def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_x_squared(x):
    if x == 1:
        return 1
    factors = get_prime_factorization(x)
    tau = 1
    for prime, exponent in factors.items():
        # If x = p1^a1 * p2^a2, then x^2 = p1^(2a1) * p2^(2a2)
        # tau(x^2) = (2a1 + 1) * (2a2 + 1)
        tau *= (2 * exponent + 1)
    return tau

def N_x(x):
    if x == 0:
        return 0
    tau = tau_x_squared(x)
    # N(x) = (tau(x^2) - 1) / 2
    return (tau - 1) // 2

